mapper.select:
SELECT P.POLL_ID, P.TITLE, P.START_YMD, P.END_YMD, P.USE_YN, P.REGIST_DT, COALESCE((SELECT SUM(VOTE_CNT) FROM POLL_ITEM WHERE POLL_ID = P.POLL_ID), 0) AS TOTAL_VOTE FROM POLL P
AND P.TITLE LIKE '%' || #{searchKeyword} || '%'
AND P.USE_YN = #{useYn}
ORDER BY P.REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM POLL P
AND P.TITLE LIKE '%' || #{searchKeyword} || '%'
AND P.USE_YN = #{useYn}

mapper.update:
UPDATE POLL_ITEM
SET VOTE_CNT = COALESCE(VOTE_CNT, 0) + 1
WHERE ITEM_ID = #{itemId}
